using System;using System.IO;using UnityEngine;using UnityEditor;using Demo6.Game;
public static class HeroV5Import{
public sealed class Part{public string id;public float[] pivot;}
public static object Run(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");const string root="아트/정수리/검사-v5-망토와무기",target="Assets/Art/TopDown/PlayerV5",artPath="Assets/Data/Combat/CombatArtSet.asset";var art=AssetDatabase.LoadAssetAtPath<CombatArtSet>(artPath);if(EditorUtility.IsDirty(art))throw new Exception("Unsaved art asset preserved");string backup="검증/플레이-사용성-v5/before-code/"+artPath;Directory.CreateDirectory(Path.GetDirectoryName(backup));if(!File.Exists(backup))File.Copy(artPath,backup);
var parts=Newtonsoft.Json.JsonConvert.DeserializeObject<Part[]>(File.ReadAllText(root+"/manifest.json"));Directory.CreateDirectory(target);foreach(var p in parts){var path=target+"/"+p.id+".png";File.Copy(root+"/runtime-PNG/"+p.id+".png",path,true);AssetDatabase.ImportAsset(path);var t=(TextureImporter)AssetImporter.GetAtPath(path);t.textureType=TextureImporterType.Sprite;t.spriteImportMode=SpriteImportMode.Single;t.spritePixelsPerUnit=256;var settings=new TextureImporterSettings();t.ReadTextureSettings(settings);settings.spriteAlignment=(int)SpriteAlignment.Custom;settings.spritePivot=new Vector2(p.pivot[0],p.pivot[1]);settings.spriteMeshType=SpriteMeshType.FullRect;t.SetTextureSettings(settings);t.alphaIsTransparency=true;t.mipmapEnabled=true;t.filterMode=FilterMode.Trilinear;t.wrapMode=TextureWrapMode.Clamp;t.textureCompression=TextureImporterCompression.Uncompressed;t.maxTextureSize=1024;t.SaveAndReimport();}
Sprite S(string id)=>AssetDatabase.LoadAssetAtPath<Sprite>(target+"/"+id+".png");art.topDown.player.cape=S("short_cape");art.topDown.weapons.greatsword=S("greatsword");art.topDown.weapons.twinblade=S("twinblade");EditorUtility.SetDirty(art);AssetDatabase.SaveAssetIfDirty(art);return new{parts=parts.Length,target};}}
